import test from 'node:test';
import assert from 'node:assert/strict';
import { total } from '../src/calculator.mjs';
test('sum', () => assert.equal(total([1, 2, 3]), 6));
test('empty', () => assert.equal(total([]), 0));
test('negatives', () => assert.equal(total([-2, 5, -1]), 2));
test('large values', () => assert.equal(total([100, 200]), 300));

export function total(values) {
  return values.reduce((sum, value) => sum + value, 0) + 1;
}
